import React, { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';
import { NAV_ITEMS } from '../constants';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${
      isScrolled ? 'bg-brand-primary/95 backdrop-blur-md py-4 shadow-lg' : 'bg-transparent py-6'
    }`}>
      <div className="max-w-7xl mx-auto px-6 lg:px-12 flex justify-between items-center">
        <div className="flex flex-col">
          <span className={`text-xl font-serif font-bold tracking-widest transition-colors duration-300 ${
            isScrolled ? 'text-brand-accent' : 'text-white'
          }`}>
            MONGE VARGAS
          </span>
          <span className={`text-[10px] tracking-[0.2em] font-medium transition-colors duration-300 ${
            isScrolled ? 'text-gray-400' : 'text-gray-300'
          }`}>
            & ASOCIADOS
          </span>
        </div>

        {/* Desktop Menu */}
        <div className="hidden md:flex space-x-8 items-center">
          {NAV_ITEMS.map((item) => (
            <a
              key={item.label}
              href={item.href}
              className={`text-xs uppercase tracking-widest font-medium transition-colors hover:text-brand-accent ${
                isScrolled ? 'text-gray-300' : 'text-gray-200'
              }`}
            >
              {item.label}
            </a>
          ))}
          <a
            href="#contacto"
            className="px-6 py-2 border border-brand-accent text-brand-accent text-xs uppercase tracking-widest font-bold hover:bg-brand-accent hover:text-brand-primary transition-all duration-300"
          >
            Consulta
          </a>
        </div>

        {/* Mobile Toggle */}
        <button 
          className="md:hidden text-white"
          onClick={() => setIsOpen(!isOpen)}
        >
          {isOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="absolute top-0 left-0 w-full h-screen bg-brand-primary flex flex-col items-center justify-center space-y-8 z-40">
          <button 
            className="absolute top-6 right-6 text-white"
            onClick={() => setIsOpen(false)}
          >
            <X size={32} />
          </button>
          {NAV_ITEMS.map((item) => (
            <a
              key={item.label}
              href={item.href}
              onClick={() => setIsOpen(false)}
              className="text-xl text-white font-serif tracking-widest hover:text-brand-accent transition-colors"
            >
              {item.label}
            </a>
          ))}
        </div>
      )}
    </nav>
  );
};

export default Navbar;

