import ConsultationForm from './components/ConsultationForm';
import Footer from './components/Footer';

const App: React.FC = () => {
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    setIsLoaded(true);

    const observerOptions = {
      threshold: 0.1,
      rootMargin: '0px 0px -50px 0px'
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('active');
        }
      });
    }, observerOptions);

    const revealElements = document.querySelectorAll('.reveal');
    revealElements.forEach(el => observer.observe(el));

    // LÓGICA DE NAVEGACIÓN CRÍTICA: 
    // Si el usuario hace clic en un link o la URL tiene un hash, 
    // forzamos la visibilidad de esa sección para que no se vea "negro".
    const handleHashChange = () => {
      const hash = window.location.hash;
      if (hash) {
        const target = document.querySelector(hash);
        if (target) {
          // Si el target es un reveal o está dentro de uno, activamos
          target.classList.add('active');
          const parentReveal = target.closest('.reveal');
          if (parentReveal) parentReveal.classList.add('active');
        }
      }
    };

    window.addEventListener('hashchange', handleHashChange);
    // Ejecutar al inicio por si ya viene con hash
    handleHashChange();

    return () => {
      observer.disconnect();
      window.removeEventListener('hashchange', handleHashChange);
    };
  }, []);

  return (
    <div className={`transition-opacity duration-500 ${isLoaded ? 'opacity-100' : 'opacity-0'} bg-brand-neutralLight min-h-screen`}>
      <Navbar />
      <main>
        {/* Hero sin reveal para visibilidad inmediata */}
        <Hero />

        {/* IDs movidos a los contenedores reveal para precisión en el scroll */}
        <div id="nosotros" className="reveal">
          <About />
        </div>

        <div id="servicios" className="reveal">
          <Services />
        </div>

        <div id="sectores" className="reveal">
          <Sectors />
        </div>

        <div id="metodologia" className="reveal">
          <Methodology />
        </div>

        <div className="reveal">
          <Compliance />
        </div>

        <div id="agendar" className="reveal">
          <ConsultationForm />
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default App;

