import Methodology from './components/Methodology';
import Compliance from './components/Compliance';
import ConsultationForm from './components/ConsultationForm';
import Footer from './components/Footer';

const App: React.FC = () => {
  useEffect(() => {
    // 1. Intersection Observer para revelado elegante al hacer scroll manual
    const observerOptions = {
      threshold: 0.1,
      rootMargin: '0px 0px -50px 0px'
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('active');
        }
      });
    }, observerOptions);

    const revealElements = document.querySelectorAll('.reveal');
    revealElements.forEach(el => observer.observe(el));

    // 2. Interceptor de navegación para botones y enlaces de menú
    const handleInternalNavigation = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const anchor = target.closest('a');

      if (anchor && anchor.hash && anchor.hash.startsWith('#')) {
        const id = anchor.hash.substring(1);
        const destination = document.getElementById(id);

        if (destination) {
          // Forzar visibilidad inmediata antes de que termine el scroll
          destination.classList.add('active');

          // Si el destino es un hijo de un contenedor reveal, activar el padre
          const parentReveal = destination.closest('.reveal');
          if (parentReveal) parentReveal.classList.add('active');
        }
      }
    };

    document.addEventListener('click', handleInternalNavigation);

    // 3. Manejar hash al cargar la página (por si el usuario refresca en una sección)
    if (window.location.hash) {
      const initialId = window.location.hash.substring(1);
      const initialTarget = document.getElementById(initialId);
      if (initialTarget) {
        initialTarget.classList.add('active');
        initialTarget.closest('.reveal')?.classList.add('active');
      }
    }

    return () => {
      observer.disconnect();
      document.removeEventListener('click', handleInternalNavigation);
    };
  }, []);

  return (
    <div className="bg-brand-neutralLight min-h-screen">
      <Navbar />
      <main>
        {/* El Hero siempre está visible al inicio, no lleva clase reveal */}
        <section id="inicio">
          <Hero />
        </section>

        <div id="nosotros" className="reveal">
          <About />
        </div>

        <div id="servicios" className="reveal">
          <Services />
        </div>

        <div id="sectores" className="reveal">
          <Sectors />
        </div>

        <div id="metodologia" className="reveal">
          <Methodology />
        </div>

        <div className="reveal">
          <Compliance />
        </div>

        <div id="agendar" className="reveal">
          <ConsultationForm />
        </div>
      </main>
      <Footer />
    </div>
  );
};

