    // 2. NAVEGACIÓN SEGURA: Interceptamos todos los clics en enlaces internos
    const handleGlobalClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const anchor = target.closest('a');

      if (anchor && anchor.hash && anchor.hash.startsWith('#')) {
        const id = anchor.hash.substring(1);
        const element = document.getElementById(id);

        if (element) {
          e.preventDefault(); // Evitamos que el navegador haga un "salto" brusco o recargue

          // Activamos la visibilidad de la sección de destino INMEDIATAMENTE
          element.classList.add('active');
          const parentReveal = element.closest('.reveal');
          if (parentReveal) parentReveal.classList.add('active');

          // Desplazamiento suave manual
          const offset = 80; // Compensación del Navbar
          const bodyRect = document.body.getBoundingClientRect().top;
          const elementRect = element.getBoundingClientRect().top;
          const elementPosition = elementRect - bodyRect;
          const offsetPosition = elementPosition - offset;

          window.scrollTo({
            top: offsetPosition,
            behavior: 'smooth'
          });

          // Actualizamos la URL sin recargar
          window.history.pushState(null, '', `#${id}`);
        }
      }
    };

    document.addEventListener('click', handleGlobalClick);

    return () => {
      observer.disconnect();
      document.removeEventListener('click', handleGlobalClick);
    };
  }, []);

  return (
    <div className="bg-brand-neutralLight min-h-screen">
      <Navbar />
      <main>
        {/* El Hero siempre debe estar visible */}
        <Hero />
        <About />
        <Services />
        <Sectors />
        <Methodology />
        <Compliance />
        <ConsultationForm />
      </main>
      <Footer />
    </div>
  );
};

export default App;

